"Optional · selected task evidence is sent to TypeSafe when you run. Provider usage charges apply. PandaCode works without Jev. Advice does not change files, models, or permissions.": "Optional · Beim Ausführen werden ausgewählte Aufgabenbelege an TypeSafe gesendet. Provider-Nutzungsgebühren entstehen. PandaCode funktioniert ohne Jev. Hinweise ändern keine Dateien, Modelle oder Berechtigungen.",
