"PandaCode has no “{0}” view. Showing its data instead.": "PandaCode hat keine Ansicht \"{0}\". Stattdessen werden ihre Daten angezeigt.",
"PandaCode quick launcher": "PandaCode-Schnellstarter",
"PandaCode restarts when your agents are done and you step away.": "PandaCode startet neu, wenn Ihre Agents fertig sind und Sie weg sind.",
"PandaCode runs Linux and macOS VMs on Apple's Virtualization framework: headless, and only the memory you give it.": "PandaCode betreibt Linux- und macOS-VMs auf Apples Virtualization-Framework: ohne Bildschirm und nur mit dem Speicher, den Sie zuweisen.",
"PandaCode tools": "PandaCode-Tools",
"PandaCode uses it to check that messages really come from Meta.": "PandaCode verwendet es, um zu prüfen, dass Nachrichten wirklich von Meta kommen.",
"PandaCode will restart to update when your agents finish.": "PandaCode startet zur Aktualisierung neu, sobald Ihre Agents fertig sind.",
"PandaCode works without Jev or a TypeSafe key. Optional decision assistance only needs the key for the provider you pick. OpenRouter models are listed only when you open the model menu. Keys are saved privately on this device, outside the keychain. Leave a field empty to keep its saved key.": "PandaCode funktioniert ohne Jev oder einen TypeSafe-Schlüssel. Die optionale Entscheidungshilfe braucht nur den Schlüssel des Providers, den Sie wählen. OpenRouter-Modelle werden nur aufgelistet, wenn Sie das Modellmenü öffnen. Schlüssel werden privat auf diesem Gerät gespeichert, außerhalb des Schlüsselbunds. Lassen Sie ein Feld leer, um seinen gespeicherten Schlüssel zu behalten.",
"PandaCode {0} is available.": "PandaCode {0} ist verfügbar.",
