"PandaCode {0} is available. Updates for this copy are installed by its package or a new AppImage.": "PandaCode {0} ist verfügbar. Updates für diese Kopie werden über ihr Paket oder ein neues AppImage installiert.",
"PandaCode {0} is ready. Restart now, or it restarts on its own when your agents are done.": "PandaCode {0} ist bereit. Starten Sie jetzt neu, oder es startet von selbst neu, wenn Ihre Agents fertig sind.",
