"Read-only metadata from local harness configs and recorded usage.": "Schreibgeschützte Metadaten aus lokalen Agent-Konfigurationen und aufgezeichneter Nutzung.",
"Read-only sandbox: DeepSeek cannot write files and proposes a plan; requests to escalate are declined.": "Schreibgeschützte Sandbox: DeepSeek kann keine Dateien schreiben und schlägt einen Plan vor; Ausweitungsanfragen werden abgelehnt.",
"Read-only: Command Code researches and plans; edits and commands are declined.": "Schreibgeschützt: Command Code recherchiert und plant; Bearbeitungen und Befehle werden abgelehnt.",
"Read-only: Grok investigates and proposes a plan; edits and commands are declined.": "Schreibgeschützt: Grok untersucht und schlägt einen Plan vor; Bearbeitungen und Befehle werden abgelehnt.",
"Read-only: Kilo investigates and plans; edits, commands and other state-changing tools are declined.": "Schreibgeschützt: Kilo untersucht und plant; Bearbeitungen, Befehle und andere zustandsändernde Tools werden abgelehnt.",
"Read-only: Muse cannot write files or run shell commands, and proposes a plan.": "Schreibgeschützt: Muse kann keine Dateien schreiben oder Shell-Befehle ausführen und schlägt einen Plan vor.",
