"Reads account limits from your locally configured agent accounts. Requests go directly to the provider or its CLI, never through PandaCode servers. No prompts are sent. Results are cached for one minute; Refresh is limited to once every ten seconds per provider. Some providers do not expose their limits. Usage is shared with other apps using the same account.": "Liest Kontolimits aus Ihren lokal konfigurierten Agent-Konten. Anfragen gehen direkt an den Provider oder seine CLI, nie über PandaCode-Server. Es werden keine Prompts gesendet. Ergebnisse werden eine Minute zwischengespeichert; Aktualisieren ist auf einmal alle zehn Sekunden pro Provider begrenzt. Manche Provider legen ihre Limits nicht offen. Die Nutzung wird mit anderen Apps geteilt, die dasselbe Konto verwenden.",
