"This Kimi model does not advertise the selected thinking setting. Choose another setting or use harness settings.": "Dieses Kimi-Modell kündigt die gewählte Denkeinstellung nicht an. Wählen Sie eine andere Einstellung oder die Agent-Einstellungen.",
